INSERT INTO #newcmt ([song_id],[source],[content],[likes],[comment_time]) VALUES
(N'207', N'netease', N'抖音才刷到创作过程，马上跑过来听', N'4', N'2024-07-16'),
(N'207', N'netease', N'把我唱得想屋头了[多多大哭][多多大哭][多多大哭]本来就惨，高考不努力跑到外头读大学[多多大哭][多多大哭][多多大哭]，今天放行李箱列车长说我小伙子你怎么抬个行李箱就脸红了，但他不知道大大的行李箱装满了沉甸甸的爱。现在躺在床上感觉床好硬，想我的狗，想我的内江牛肉面我要777，想我的绵阳米粉', N'33', N'2024-03-18'),
(N'207', N'netease', N'此曲值得单曲N次循环！', N'4', N'2024-10-24'),
(N'207', N'netease', N'幺儿豁开开[多多大哭]', N'6', N'2026-07-19'),
(N'207', N'netease', N'叫我幺儿的人已经离开我300多天了', N'43', N'2026-07-05'),
(N'207', N'netease', N'一句就把人唱哭，太强了', N'1', N'2025-05-07'),
(N'207', N'netease', N'好想回家', N'2', N'2024-10-25'),
(N'207', N'netease', N'刚听到的时候 离家的情绪瞬间涌上心头，为了生活奔波。城里的人想出城，城外的人想进城。[皱眉][皱眉]', N'2', N'2024-06-02'),
(N'207', N'netease', N'想回家了', N'1', N'2025-07-07'),
(N'207', N'netease', N'城市的路那么宽，一环套一环，回家的路说远不远，却总没时间', N'3', N'2024-02-13'),
(N'207', N'netease', N'必定大火', N'1', N'2025-04-14'),
(N'207', N'netease', N'幺儿这两个字对四川人来说冲击太大了[多多难过][多多难过][多多难过]', N'37', N'2025-09-08'),
(N'207', N'netease', N'泪目了，一个30岁的离异在外的男人，大学毕业快10年了，感觉挺失败的，家庭没照顾好，工作也一般，唉！', N'1', N'2025-01-02'),
(N'207', N'netease', N'妈妈 我想回家', N'1', N'2025-11-03'),
(N'207', N'netease', N'太美好的歌 和我奶奶话一模一样', N'2', N'2026-03-23'),
(N'207', N'netease', N'不行，听就想哭😭', N'2', N'2026-03-07'),
(N'207', N'netease', N'我们踩着柏油路上的倒影追逐远方。  那些被996碾碎的"按时吃饭"，在视频通话的像素格里蒸腾成雾，湿润了电子屏幕两端刻意藏起的皱纹与白发。', N'12', N'2025-12-11'),
(N'207', N'netease', N'故乡的蝉鸣穿透记忆的褶皱，碎裂的瓦片漏下的不只是天光，更是被岁月切割成碎片的童年。  城市的霓虹再亮，却照不亮游子心里那条蜿蜒的田埂路，高楼间的月光被切割成二维码，再也扫不出母亲在灶台前拉长的身影。', N'10', N'2026-02-26'),
(N'207', N'netease', N'对于今天过生日，又远离家乡四川的我来说，太想哭了[流泪][流泪][流泪]', N'8', N'2025-07-25'),
(N'207', N'netease', N'泪目[流泪]', N'2', N'2026-06-21'),
(N'207', N'netease', N'一听这首歌我就想回家[流泪]', N'0', N'2024-09-24'),
(N'207', N'netease', N'有版权了，有资源了。真好。', N'1', N'2026-05-14'),
(N'207', N'netease', N'音乐作品很好听，就是文字翻译，错得太多了。那个叫：凌啊子（蝉），哪里是什么米嘎子。能不能好生找个川渝的人来翻译一下。实在找不到，联系我嘛，我来给你翻译。不然翻译拉垮了整体评分。', N'4', N'2026-05-26'),
(N'207', N'netease', N'我有一张我爸两岁和奶奶的照片。他穿着川东老家小朋友特有的装束，那种只有一个兜的围腰，腼腆地跤着腿，在奶奶身边腼腆地对着镜头微笑。这位可爱的小朋友，生于1955年，他在2020年直肠癌去世了。这歌，像是我奶奶在问他的幺儿，令我无言以对，羞愧难当，泪流满面，无言以答。', N'19', N'2026-01-06'),
(N'207', N'netease', N'终于上传了', N'0', N'2024-06-28'),
(N'207', N'netease', N'阿婆我好想你', N'2', N'2026-01-20'),
(N'207', N'netease', N'长大后老家只有冬天', N'12', N'2024-01-08'),
(N'207', N'netease', N'在陕西读书，上上个月家里出事突然通知我回家，最后一站列车还有半个小时，我马不停蹄奔向高铁站，差一分钟，就差一分钟我就赶上了。我站在售票处哭得站不住脚，等不到第二天的高铁，坐了14小时的火车回家。陕西到自贡，是800多公里的距离，300块钱的车票，是说不出的牵挂说不完的思念和担忧。', N'9', N'2025-11-06'),
(N'207', N'netease', N'很好听～', N'0', N'2025-11-13'),
(N'207', N'netease', N'我愿称这首歌为四川省省歌', N'88', N'2024-05-29'),
(N'207', N'netease', N'出来就想家了，回家吃饭', N'2', N'2025-04-16'),
(N'207', N'netease', N'东北人在川工作好几年了，理解了适应了这片土地之后再听，这句“幺儿”喊的何尝不是我啊', N'10', N'2025-06-03'),
(N'207', N'netease', N'笛子是丁老师！', N'0', N'2025-09-15'),
(N'207', N'netease', N'此歌必火！', N'2', N'2025-05-20'),
(N'207', N'netease', N'年轻时，游走四方。年纪大了，梦回家乡。', N'2', N'2024-03-14'),
(N'207', N'netease', N'《走出大山》后来走出了这座大山，去到了山的那一边，去了很多地方，去看了更多的名山大川，而这座大山只有每年过年来一次… …这座山成了心中的眷恋……', N'9', N'2024-01-08'),
(N'207', N'netease', N'去年4月底被老大霍来广东 一腔遂宁的口音 把我又扯回了涪江边边的那个半山坡上 听得我想甩了老大跑回去了 想的不是家，想的是成长历程见证地 射洪～柳树～', N'6', N'2026-01-03'),
(N'207', N'netease', N'四川到西藏1800多公里，出川都21年了[流泪]', N'6', N'2025-08-03'),
(N'207', N'netease', N'视频号刷到，过来收藏', N'4', N'2024-01-31'),
(N'207', N'netease', N'初听不知曲中意再听已是曲中人[心碎]', N'0', N'2024-08-17'),
(N'207', N'netease', N'故乡是用来怀念的，青春就是用来追忆的，当你怀揣着它时，它一文不值，只有将它耗尽后，再回过头看，一切才有了意义。', N'3', N'2024-12-15'),
(N'207', N'netease', N'声音很像我奶奶，也让我想起了奶奶。希望所有的幺儿，被喊幺儿，或者喊你幺儿的人，都健健康康平平安安。', N'6', N'2024-08-10'),
(N'207', N'netease', N'真的是催泪弹', N'2', N'2026-07-26'),
(N'207', N'netease', N'自贡在广州遭不住了', N'4', N'2024-10-06'),
(N'207', N'netease', N'人言落日是天涯，望极天涯不见家。乡音无改，戎马倥偬，边关冷月，年复一年。', N'0', N'2026-08-21'),
(N'207', N'netease', N'一路走来的委屈我又可以向谁诉说呢', N'3', N'2025-08-08'),
(N'207', N'netease', N'流泪了[流泪]', N'2', N'2024-09-04'),
