INSERT INTO #newcmt ([song_id],[source],[content],[likes],[comment_time]) VALUES
(N'181', N'netease', N'当时间你为何把休书来撕毁，为只为海誓山盟有恩情?当时间你要撞死在长亭上，你是生生死死表同情； 当时间左右高邻都感动，都说你贞娘有良心?哪知你言犹在耳你心已变，你贪图富贵就嫁进帅府门?,1479461479486"', N'0', N'2024-06-16'),
(N'181', N'netease', N'高俅是他们父子同谋施毒计，害得你恩爱夫妻两离分，你血海冤仇有万丈深?自古道恩怨两字要分明白，你不分恩怨是枉为人。你怎把这个仇人去当亲人?（也罢！）与你一刀两段来分手，从今割断父女情，不许你再上我家门?,1479460668746"', N'0', N'2024-06-16'),
(N'181', N'netease', N'张调，表现力极强，高亢处声如裂帛，低沉处如泣似诉，有令人倾倒的艺术感染力。特别是：张老。中气充沛、咬字遒劲、苍劲激昂、韵味浓郁！喜欢！百听不厌！', N'0', N'2024-06-16'),
(N'181', N'netease', N'张老的经典，听着过赢?,1479456524567"', N'0', N'2024-06-16'),
(N'181', N'netease', N'今年?1岁，但我就是喜欢听三?,1474880183818"', N'0', N'2024-06-16'),
(N'181', N'netease', N'张教头是怒满胸膛，骂一?,1472780528509"', N'0', N'2024-06-16'),
(N'181', N'netease', N'1.4639E+12', N'0', N'2024-06-16'),
(N'181', N'netease', N'张教头怒满胸膛骂一声，骂声贞娘不该应。你说出话来真无耻，你忘了冤仇变了心。你全不想，丈夫被害遭冤屈，你全不想，林冲发配去充军。长亭泣别言犹在，怎能够你贪图富贵允了婚。想那林冲生死未明白，纵然林冲丧了命，你怎能嫁进帅府门。高俅是父子同谋施毒计，害得你恩爱夫妻两离分，你血海冤仇万丈深', N'0', N'2024-06-16'),
(N'181', N'netease', N'1.44688E+12', N'0', N'2024-06-16'),
