-- 插入: id 从 MAX(id)+1 开始, 且跳过DB已存在的(song_id+source+content)
DECLARE @base int = (SELECT ISNULL(MAX([id]),0) FROM [dbo].[comment]);
INSERT INTO [dbo].[comment] ([id],[song_id],[content],[likes],[source],[comment_time])
SELECT @base + ROW_NUMBER() OVER (ORDER BY n.[song_id], n.[source], n.[content]),
       n.[song_id], n.[content], n.[likes], n.[source], n.[comment_time]
FROM #newcmt AS n
WHERE NOT EXISTS (
  SELECT 1 FROM [dbo].[comment] c
  WHERE c.[song_id]=n.[song_id] AND c.[source]=n.[source] AND c.[content]=n.[content]
);
GO

DROP TABLE #newcmt;
GO
